#include <Adafruit_NeoPixel.h>


#define PIN        6
#define NUMPIXELS  7
int blue = 0;  
int d = 5;
int number = 0; 
int n = 1; 
int red = 0; 
Adafruit_NeoPixel pixels(NUMPIXELS, PIN, NEO_GRB + NEO_KHZ800);


void setup() {
  pixels.begin();
  pixels.clear();
  pixels.setBrightness(25);
  pixels.show();
}


void loop() {
  pixels.setPixelColor(number, pixels.Color(0, red, blue));
  blue = blue + d;  
  number = number + n;
  red = red + d;
  if (blue <= 0 || blue >= 255) {  
        d = -d; 
  }
  if (number <= 0 || number >= 7) {
    n = -n;
  }
  if (red <= 0 || red >= 255) {
    d = -d;
  }
  delay(30); 
  pixels.show();
  }
